const row = $input.first().json || {};
const rows = Array.isArray(row.rows) ? row.rows : [];
function rescueCandidate(event) {
  const key = String(event.button_key || '').toLowerCase();
  return String(event.status || '').toUpperCase() === 'STALE'
    && String(event.reason || '').toLowerCase() === 'stale_state'
    && /^plan_[a-z0-9_]+_(12|24|36)m$/.test(key)
    && String(event.conversation_state || '').toUpperCase() === 'PLAN_SELECTED'
    && String(event.active_interaction_type || '').toUpperCase() === 'PLAN_SELECTION'
    && event.active_interaction_id
    && event.interaction_id
    && event.active_interaction_id === event.interaction_id
    && event.interaction_consumed !== true
    && event.automation_enabled !== false
    && event.human_handoff !== true
    && event.conversation_id
    && event.chatwoot_conv_id;
}
const claimToken = new Date().toISOString();
return rows.filter(rescueCandidate).map(event => ({ json: { ...event, rescue_source: 'OPS-11', rescue_candidate: true, rescue_claim_token: claimToken } }));

const claimed = $('PG - Verify Plan Rescue Claim').all().map(item => item.json || {});
function responsePayload(resp) {
  if (Array.isArray(resp?.body?.payload)) return resp.body.payload;
  if (Array.isArray(resp?.body?.data?.payload)) return resp.body.data.payload;
  if (Array.isArray(resp?.payload)) return resp.payload;
  if (Array.isArray(resp?.data?.payload)) return resp.data.payload;
  if (Array.isArray(resp?.body)) return resp.body;
  if (Array.isArray(resp)) return resp;
  return [];
}
function messageTimeMs(message) {
  const raw = message.created_at || message.createdAt || message.timestamp;
  if (!raw) return NaN;
  if (typeof raw === 'number') return raw > 100000000000 ? raw : raw * 1000;
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? parsed : NaN;
}
function isPublicOutgoing(message) {
  const type = String(message.message_type ?? message.messageType ?? '').toLowerCase();
  const senderType = String(message.sender_type || message.sender?.type || '').toLowerCase();
  return message.private !== true
    && (message.message_type === 1 || type === '1' || type === 'outgoing' || senderType === 'agent' || senderType === 'user');
}
function planParts(buttonKey) {
  const m = /^plan_([a-z0-9_]+)_(12|24|36)m$/.exec(String(buttonKey || '').toLowerCase());
  if (!m) return { code: '', duration: '' };
  return { code: m[1].toUpperCase(), duration: m[2] };
}
function titleFromPlanCode(code) {
  return String(code || 'plan seleccionado')
    .split('_')
    .filter(Boolean)
    .map(part => part.charAt(0).toUpperCase() + part.slice(1).toLowerCase())
    .join(' ');
}
function cleanPhone(value) {
  const raw = String(value || '').trim();
  return raw.startsWith('+') ? raw.slice(1) : raw;
}
function buildPayload(candidate) {
  const parts = planParts(candidate.button_key);
  const duration = candidate.selected_plan_duration || parts.duration || '';
  const planName = candidate.selected_plan_name || candidate.selected_plan || titleFromPlanCode(parts.code);
  const price = candidate.selected_plan_price;
  const durationText = duration ? ' a ' + duration + ' meses' : '';
  const priceText = price !== undefined && price !== null && price !== '' && Number.isFinite(Number(price)) ? ' por $' + Number(price).toFixed(2) : '';
  const bodyText = 'Perfecto, dejé registrada la opción ' + planName + durationText + priceText + '. ¿Desea que un asesor lo contacte para continuar?';
  return {
    messaging_product: 'whatsapp',
    to: cleanPhone(candidate.phone),
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: bodyText.slice(0, 1024) },
      action: {
        button: 'Elegir opción',
        sections: [{
          title: 'Siguiente paso',
          rows: [
            { id: 'si_quiero_contratar', title: 'Sí, quiero contratar', description: 'Coordinar contratación e instalación' },
            { id: 'contactar_a_un_asesor', title: 'Hablar con asesor', description: 'Resolver dudas con un especialista' },
            { id: 'revisar_otro_plan', title: 'Revisar otro plan', description: 'Volver a comparar opciones' }
          ]
        }]
      }
    }
  };
}
function skipped(candidate, status, failure, extra = {}) {
  return { json: { ...candidate, rescue_should_send: false, rescue_status: status, rescue_failure: failure, ...extra } };
}
const output = [];
for (const [index, item] of $input.all().entries()) {
  const candidate = claimed[index] || {};
  const resp = item.json || {};
  const statusCode = Number(resp.statusCode || resp.status || 0);
  const httpOk = statusCode >= 200 && statusCode < 300;
  const eventMs = Date.parse(candidate.created_at || '');
  const messages = responsePayload(resp);
  const publicAfter = messages.find(message => isPublicOutgoing(message) && Number.isFinite(messageTimeMs(message)) && Number.isFinite(eventMs) && messageTimeMs(message) > eventMs);
  if (candidate.has_active_proposal_confirmation === true) {
    output.push(skipped(candidate, 'RESCUE_SKIPPED_EXISTING_PROPOSAL', 'active_proposal_confirmation_exists', { chatwoot_http_status: statusCode || null }));
    continue;
  }
  if (!httpOk) {
    output.push(skipped(candidate, 'RESCUE_SKIPPED_CHATWOOT_UNVERIFIED', 'chatwoot_http_' + (statusCode || 'unknown'), { chatwoot_http_status: statusCode || null }));
    continue;
  }
  if (publicAfter) {
    output.push(skipped(candidate, 'RESCUE_SKIPPED_PUBLIC_REPLY', 'public_reply_after_event', { public_reply_message_id: publicAfter.id || null, chatwoot_http_status: statusCode || null }));
    continue;
  }
  output.push({ json: { ...candidate, rescue_should_send: true, rescue_status: 'RESCUE_READY_TO_SEND', chatwoot_http_status: statusCode || null, meta_payload: buildPayload(candidate) } });
}
return output;

const source = $('Code - Prepare Plan Rescue Send').all().map(item => item.json || {});
const results = [];
for (const [index, item] of $input.all().entries()) {
  const candidate = source[index] || {};
  const response = item.json || {};
  const statusCode = Number(response.statusCode || response.status || 0);
  const body = response.body || response;
  const metaMessageId = body?.messages?.[0]?.id || response?.messages?.[0]?.id || null;
  const sent = statusCode >= 200 && statusCode < 300 && Boolean(metaMessageId);
  results.push({ json: {
    ...candidate,
    meta_sent: sent,
    meta_http_status: statusCode || null,
    meta_message_id: metaMessageId,
    rescue_status: sent ? 'RESCUED' : 'RESCUE_FAILED_META_SEND',
    rescue_failure: sent ? null : (body?.error?.message || response?.error?.message || 'meta_send_failed')
  } });
}
return results;

const row = $input.first().json || {};
const rows = Array.isArray(row.rows) ? row.rows : [];
const staticData = $getWorkflowStaticData('global');
staticData.alerted = staticData.alerted || {};
const now = new Date();
const cutoffMs = now.getTime() - 24 * 60 * 60 * 1000;
for (const [key, value] of Object.entries(staticData.alerted)) {
  if (!value || new Date(value).getTime() < cutoffMs) delete staticData.alerted[key];
}
function keyFor(event) {
  return 'silent-button:' + (event.event_id || event.wa_message_id || [event.conversation_id, event.button_key, event.reason, event.created_at].join(':'));
}
function clip(value, max = 80) {
  const text = String(value == null ? '' : value).trim();
  return text.length > max ? text.slice(0, max - 3) + '...' : (text || '-');
}
function phoneTail(value) {
  const digits = String(value || '').replace(/\D/g, '');
  return digits ? '***' + digits.slice(-4) : '-';
}
const fresh = [];
for (const event of rows) {
  const dedupeKey = keyFor(event);
  if (staticData.alerted[dedupeKey]) continue;
  fresh.push({ ...event, dedupe_key: dedupeKey });
}
if (!fresh.length) {
  return [{ json: {
    send_alert: false,
    status: 'no_new_silent_button_claims',
    checked_at: row.checked_at || now.toISOString(),
    candidate_count: rows.length,
  } }];
}
const lines = [
  'CRIS OPS-11 - Silent button sentinel',
  'Nuevos bloqueos comerciales: ' + fresh.length,
  'Ventana: ultimos 15 minutos',
  '',
];
for (const event of fresh.slice(0, 10)) {
  lines.push([
    '- cw=' + clip(event.chatwoot_conv_id),
    'phone=' + phoneTail(event.phone),
    'state=' + clip(event.conversation_state, 24),
    'button=' + clip(event.button_key, 48),
    'status=' + clip(event.status, 16),
    'reason=' + clip(event.reason, 48),
    'interaction=' + clip(event.interaction_id, 44),
  ].join(' | '));
}
if (fresh.length > 10) lines.push('... +' + (fresh.length - 10) + ' mas');
lines.push('');
lines.push('Accion: revisar si hubo respuesta publica o rescate manual. Duplicado fisico wa_message_id esta excluido.');
return [{ json: {
  send_alert: true,
  status: 'silent_button_alert_pending',
  checked_at: row.checked_at || now.toISOString(),
  candidate_count: rows.length,
  alert_count: fresh.length,
  dedupe_keys: fresh.map(event => event.dedupe_key),
  rows: fresh,
  meta_payload: {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: '5521999910781',
    type: 'text',
    text: { preview_url: false, body: lines.join('\n').slice(0, 3900) },
  },
} }];

const build = $('Code - Build Alert').first().json || {};
const staticData = $getWorkflowStaticData('global');
staticData.alerted = staticData.alerted || {};
