const source = $('Code - Split Processed Reply Watch').all().map(item => item.json || {});
const input = $input.all();
const staticData = $getWorkflowStaticData('global');
staticData.processedReplyWatchAlerted = staticData.processedReplyWatchAlerted || {};
const now = new Date();
const cutoffMs = now.getTime() - 24 * 60 * 60 * 1000;
for (const [key, value] of Object.entries(staticData.processedReplyWatchAlerted)) {
  if (!value || new Date(value).getTime() < cutoffMs) delete staticData.processedReplyWatchAlerted[key];
}
function eventTs(event) {
  const parsed = Date.parse(event.created_at || '');
  return Number.isFinite(parsed) ? Math.floor(parsed / 1000) : 0;
}
function msgTs(message) {
  const raw = message?.created_at || 0;
  if (typeof raw === 'number') return raw > 100000000000 ? Math.floor(raw / 1000) : raw;
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? Math.floor(parsed / 1000) : 0;
}
function responsePayload(resp) {
  if (Array.isArray(resp?.body?.payload)) return resp.body.payload;
  if (Array.isArray(resp?.payload)) return resp.payload;
  if (Array.isArray(resp?.data?.payload)) return resp.data.payload;
  if (Array.isArray(resp?.data)) return resp.data;
  if (Array.isArray(resp)) return resp;
  return [];
}
function isPublicOutgoing(message) {
  if (!message || message.private === true || message.content_attributes?.deleted === true) return false;
  const type = String(message.message_type ?? '').toLowerCase();
  if (type === '2' || type === 'activity') return false;
  return type === '1' || type === 'outgoing' || ['user', 'agent', 'agent_bot', 'bot'].includes(String(message.sender_type || message.sender?.type || '').toLowerCase());
}
function keyFor(event) {
  return 'processed-reply-watch:' + (event.event_id || event.wa_message_id || [event.conversation_id, event.button_key, event.created_at].join(':'));
}
function clip(value, max = 80) {
  const text = String(value == null ? '' : value).trim();
  return text.length > max ? text.slice(0, max - 3) + '...' : (text || '-');
}
function phoneTail(value) {
  const digits = String(value || '').replace(/[^0-9]/g, '');
  return digits ? '***' + digits.slice(-4) : '-';
}
const silent = [];
