const lines = [
  'CRIS OPS-11 - Processed button without public reply',
  'Nuevos silencios confirmados: ' + silent.length,
  'Ventana: ultimos 20 minutos',
  '',
];
for (const event of silent.slice(0, 10)) {
  lines.push([
    '- cw=' + clip(event.chatwoot_conv_id),
    'phone=' + phoneTail(event.phone),
    'state=' + clip(event.conversation_state, 24),
    'button=' + clip(event.button_key, 48),
    'processed_state=' + clip(event.processed_state, 24),
    'event=' + clip(event.event_id, 44),
  ].join(' | '));
}
if (silent.length > 10) lines.push('... +' + (silent.length - 10) + ' mas');
lines.push('');
lines.push('Accion: revisar envio publico o rescatar via OPS-07.');
return [{ json: {
  send_alert: true,
  status: 'processed_button_without_public_reply_alert_pending',
  checked_at: source[0]?.checked_at || now.toISOString(),
  candidate_count: source.length,
  alert_count: silent.length,
